-- Field IDs are unchanged so English and Spanish share the same saved-answer records.

INSERT INTO bd_content(id, blocks)
VALUES ('es:foundations', '[{"type":"field","id":"f_8258812d4c69cf","text":"Nombre","short":true},{"type":"field","id":"f_a140d9882f116e","text":"Fecha de inicio","short":true},{"type":"heading","text":"1. Aprende la lección"},{"type":"text","text":"Al terminar este cuaderno, deberías poder:"},{"type":"check","id":"f_f04190aa204c34","text":"Usa las cuatro preguntas de estudio enseñadas en la lección introductoria antes y después de estudiar la Biblia."},{"type":"check","id":"f_0b68e81dd55992","text":"Explica por qué comprender palabras e ideas bíblicas clave puede cambiar la manera de entender un pasaje."},{"type":"check","id":"f_820ad7e581f1a0","text":"Reconoce las definiciones de trabajo del curso para ira/castigo, ley, misericordia/justicia, gloria/nombre, santo, pecado y la ley del amor."},{"type":"check","id":"f_d95b2b1d9e4de3","text":"Aplica las ideas de la lección a los pasajes bíblicos que cita, en lugar de limitarte a memorizar definiciones."},{"type":"check","id":"f_856409e369ecaa","text":"Mantén tus descubrimientos conectados con el carácter de Dios, la redención y la aplicación personal."},{"type":"heading","text":"La lección de un vistazo"},{"type":"text","text":"Comienza con oración"},{"type":"text","text":"Ora por la guía del Espíritu Santo antes y después de estudiar la Biblia."},{"type":"text","text":"Pregunta sobre el carácter"},{"type":"text","text":"Pregunta: ¿Qué me dice esto acerca del carácter de Dios?"},{"type":"text","text":"Pregunta sobre la redención"},{"type":"text","text":"Pregunta: ¿De qué manera esto es redentor?"},{"type":"text","text":"Pregunta para la vida"},{"type":"text","text":"Pregunta: ¿Qué significa esto en mi vida?"},{"type":"text","text":"Aclara palabras e ideas"},{"type":"text","text":"Cuando un pasaje parezca confuso, ve más despacio y asegúrate de comprender las palabras y conceptos importantes que se están usando."},{"type":"field","text":"En tus propias palabras, ¿cuál es la habilidad o idea principal que enseña esta lección?","id":"f_ec82cf17f1bef9"},{"type":"field","text":"¿Qué parte te resulta más clara? ¿Cuál necesita más reflexión?","id":"f_4031c80778c4d3"},{"type":"heading","text":"2. Práctica guiada"},{"type":"text","text":"LAS CUATRO PREGUNTAS"},{"type":"field","text":"1. Antes de estudiar: escribe una oración breve pidiendo al Espíritu Santo que guíe tu comprensión.","id":"f_ffe342759f34e1"},{"type":"field","text":"2. ¿Qué me dice el pasaje acerca del carácter de Dios?","id":"f_3eecffe4a5a394"},{"type":"field","text":"3. ¿De qué manera esto es redentor?","id":"f_d50ebc67616845"},{"type":"field","text":"4. ¿Qué significa esto en mi vida?","id":"f_79e0136e6bb003"},{"type":"heading","text":"Ideas clave del curso"},{"type":"text","text":"Ira / castigo"},{"type":"text","text":"La lección presenta esto como Dios permitiendo que las personas cosechen los resultados naturales de sus acciones."},{"type":"text","text":"La ley de Dios"},{"type":"text","text":"La lección describe la ley moral de Dios como natural en lugar de arbitraria."},{"type":"text","text":"Misericordia + justicia"},{"type":"text","text":"La lección presenta la misericordia y la justicia de Dios como realidades que trabajan juntas en lugar de oponerse."},{"type":"text","text":"Gloria / nombre"},{"type":"text","text":"La lección conecta la gloria y el nombre con el carácter."},{"type":"text","text":"Santo"},{"type":"text","text":"La lección usa «saludable» como un sinónimo útil para comprender la santidad."},{"type":"text","text":"Pecado"},{"type":"text","text":"La lección usa «egoísmo» como una manera útil de comprender el pecado."},{"type":"text","text":"Ley"},{"type":"text","text":"La lección presenta la ley de Dios como la ley del amor."},{"type":"field","text":"¿Cuál de estas ideas cambia más la manera en que leerías un pasaje bíblico conocido? ¿Por qué?","id":"f_515afa1d2d0ab0"},{"type":"callout","text":"Romanos 1:18, 24, 26, 28","body":"La lección introductoria señala esta sección al explicar su perspectiva sobre la ira y el castigo de Dios."},{"type":"field","text":"Lee estos versículos en tu Biblia. ¿Qué acción repetida describe el pasaje que Dios realiza en los versículos 24, 26 y 28?","id":"f_29a4d4afb8fc19"},{"type":"field","text":"¿Cómo conecta la lección esa acción repetida con su definición de ira/castigo?","id":"f_8d1b6fb394e7f8"},{"type":"field","text":"¿Qué pregunta todavía querrías investigar antes de explicar esta idea a otra persona?","id":"f_82cbe43e3e9473"},{"type":"heading","text":"3. Tu turno"},{"type":"callout","text":"Levítico 11:45","body":"«Seréis, pues, santos, porque yo soy santo». La lección usa este pasaje al hablar de santidad y salud."},{"type":"field","text":"¿Cómo conecta la lección la palabra «santo» con la idea de salud en este pasaje?","id":"f_8af693bc073a59"},{"type":"field","text":"¿Qué dice la lección que cambió en la manera de pensar de Pastor Kal acerca de la obediencia a medida que creció su comprensión?","id":"f_232206ddc71a38"},{"type":"callout","text":"Juan 1:29","body":"«¡He aquí el Cordero de Dios, que quita el pecado del mundo!». La lección usa «egoísmo» como una manera de pensar acerca del pecado."},{"type":"field","text":"Reescribe la idea de Juan 1:29 usando la propuesta de la lección «pecado = egoísmo». ¿Qué enfatiza eso para ti?","id":"f_c50773625fff32"},{"type":"callout","text":"Mateo 5:17 + Romanos 7:7","body":"La lección usa estos pasajes al presentar la ley de Dios como la ley del amor y como algo que identifica el pecado."},{"type":"field","text":"¿Qué dicen estos pasajes acerca de la función de la ley?","id":"f_0d4d04c28ec945"},{"type":"field","text":"¿Cómo moldea la idea de la «ley del amor» de la lección tu manera de pensar acerca de la obediencia?","id":"f_fd13f74d332338"},{"type":"callout","text":"Elige una idea para poner a prueba","body":"Elige una de las definiciones de trabajo de la lección y estudia las referencias bíblicas relacionadas antes de llegar a una conclusión."},{"type":"field","text":"Idea que elegí:","id":"f_1e2bc2af82ca3b"},{"type":"field","text":"Referencia(s) bíblica(s) del Video 1 que examiné:","id":"f_b3c352f95d1552"},{"type":"field","text":"¿Qué detalles del texto respaldan la idea de la lección?","id":"f_f88d4536b20335"},{"type":"field","text":"¿Qué preguntas o dudas permanecen?","id":"f_4e3f0b31843391"},{"type":"heading","text":"4. Hazlo parte de tu estudio bíblico"},{"type":"field","text":"La idea del Video 1 que más me ayudó fue:","id":"f_98528c17425243"},{"type":"field","text":"Una palabra o concepto bíblico que quiero investigar con calma en lugar de suponer que ya comprendo es:","id":"f_a668e867ba3e7c"},{"type":"field","text":"Una manera en que las cuatro preguntas pueden cambiar mi lectura habitual de la Biblia es:","id":"f_441768996d25fa"},{"type":"heading","text":"Mi comprobación de fundamentos del Video 1"},{"type":"check","id":"f_4dbf68339eb37c","text":"Oré pidiendo la guía del Espíritu Santo."},{"type":"check","id":"f_944e6ed6071a86","text":"Pregunté qué revela el pasaje acerca del carácter de Dios."},{"type":"check","id":"f_90e3af6e19d882","text":"Pregunté de qué manera el pasaje es redentor."},{"type":"check","id":"f_ecf55f07116db9","text":"Pregunté qué significa el pasaje en mi vida."},{"type":"check","id":"f_52f2035369497c","text":"Presté atención a palabras e ideas importantes en lugar de suponer que ya las comprendía."},{"type":"check","id":"f_bbce404a93ed57","text":"Mantuve mis conclusiones conectadas con los pasajes usados en la lección."},{"type":"field","text":"Mi próxima acción dentro de las próximas 24 horas:","id":"f_f4220152ecbfcd"},{"type":"heading","text":"5. Observaciones de ejemplo del video introductorio"},{"type":"text","text":"Estas son observaciones de ejemplo tomadas de la lección. No pretenden reemplazar tu propio estudio cuidadoso del pasaje."},{"type":"text","text":"• La lección compara el estudio bíblico con resolver metódicamente un problema técnico: dividir el problema, investigar con cuidado y no limitarse a comenzar todo de nuevo sin pensar."},{"type":"text","text":"• La lección ofrece cuatro salvaguardas recurrentes: orar por la guía del Espíritu Santo; preguntar qué revela el pasaje acerca del carácter de Dios; preguntar de qué manera es redentor; y preguntar qué significa en tu vida."},{"type":"text","text":"• El curso presenta varias definiciones de trabajo o ideas interpretativas: ira/castigo como Dios permitiendo que las personas cosechen los resultados naturales de sus acciones; la ley de Dios como natural y no arbitraria; misericordia y justicia como armoniosas; gloria/nombre como carácter; santo como saludable; pecado como egoísmo; y ley como la ley del amor."},{"type":"text","text":"• Romanos 1:18 junto con los versículos 24, 26 y 28 se usa para apoyar la explicación de la lección sobre la ira de Dios, enfocándose en que Dios los «entrega» a los resultados de sus decisiones."},{"type":"text","text":"• Levítico 11:45, Juan 1:29, Mateo 5:17, Romanos 7:7, Éxodo 20:4-6 y 1 Juan 1:9 se encuentran entre los pasajes usados para conectar las ideas clave del curso con las Escrituras."},{"type":"text","text":"• La ilustración final «Quién / Qué / No sé / Por qué / Mañana» refuerza el punto central de la lección: la confusión puede desaparecer cuando comprendes lo que realmente significan las palabras o los nombres."},{"type":"heading","text":"Tu resumen final"},{"type":"field","text":"Explica la idea principal de esta lección a un amigo en 3 a 5 oraciones.","id":"f_64e9c1654ea4b7"},{"type":"field","text":"Escribe una pregunta que todavía tengas después de completar este cuaderno.","id":"f_48af201b29f4f3"},{"type":"text","text":"No te apresures. Usa primero lo que aprendiste con un pasaje bíblico real. La habilidad crece con la práctica."}]')
ON CONFLICT(id) DO UPDATE SET
  blocks=excluded.blocks,
  updated_at=strftime('%Y-%m-%dT%H:%M:%fZ','now');

INSERT INTO bd_content(id, blocks)
VALUES ('es:look-for-christ', '[{"type":"field","id":"f_152ef077e72f62","text":"Nombre","short":true},{"type":"field","id":"f_f84ea2f6e48969","text":"Fecha de inicio","short":true},{"type":"heading","text":"Actitud para estudiar con Bible Decoded"},{"type":"text","text":"El Video 1 estableció cuatro preguntas que conviene tener presentes al usar cada método de Bible Decoded."},{"type":"heading","text":"Mantén contigo estas cuatro preguntas"},{"type":"check","id":"f_68bdf2ff3536df","text":"Ora por la guía del Espíritu Santo."},{"type":"check","id":"f_a90216bdebee71","text":"Pregunta: ¿Qué me dice esto acerca del carácter de Dios?"},{"type":"check","id":"f_6d70a999b7fa65","text":"Pregunta: ¿De qué manera esto es redentor?"},{"type":"check","id":"f_a3d62fa1643dbe","text":"Pregunta: ¿Qué significa esto en mi vida?"},{"type":"text","text":"La lección introductoria también advierte que las herramientas de estudio pueden usarse mal. Explora con libertad, pero sigue comprobando tus conclusiones con el pasaje y su contexto."},{"type":"field","text":"¿Qué es lo que más quieres que este método te ayude a ver o comprender?","id":"f_ab548b1cda9d6f"},{"type":"heading","text":"1. Aprende el método"},{"type":"text","text":"Al terminar este cuaderno, deberías poder:"},{"type":"check","id":"f_b79bcf9650c0cc","text":"Explica por qué la lección te pide buscar a Cristo a lo largo de las Escrituras."},{"type":"check","id":"f_c586f522f45dd7","text":"Usa la pregunta «¿Dónde está Cristo?» con una historia bíblica."},{"type":"check","id":"f_f048658c2d0e6b","text":"Pregunta «¿Dónde estoy yo?» después de identificar una conexión centrada en Cristo."},{"type":"check","id":"f_596f5f5ed9556b","text":"Distingue una conexión devocional centrada en Cristo de los acontecimientos visibles de la historia."},{"type":"check","id":"f_9adefac89958e6","text":"Convierte tu descubrimiento en una aplicación personal."},{"type":"heading","text":"El método de un vistazo"},{"type":"text","text":"Pregunta central"},{"type":"text","text":"¿Dónde está Cristo en este pasaje?"},{"type":"text","text":"Segunda pregunta"},{"type":"text","text":"¿Dónde estoy yo en esta historia?"},{"type":"text","text":"Perspectivas adicionales"},{"type":"text","text":"¿Dónde está el Padre? ¿Dónde está el Espíritu Santo? ¿Dónde está la iglesia? ¿Qué muestra esto acerca de la batalla entre el bien y el mal, las relaciones o el significado profético?"},{"type":"text","text":"Propósito principal"},{"type":"text","text":"No te detengas en la información. Deja que el pasaje te lleve a una relación más profunda con Jesús."},{"type":"field","text":"En tus propias palabras, ¿cuál es la habilidad principal que enseña este video?","id":"f_78dfc13f315ee7"},{"type":"field","text":"¿Qué parte del método te resulta más fácil? ¿Cuál te resulta más difícil?","id":"f_9d86f47dc6d75f"},{"type":"heading","text":"2. Práctica guiada"},{"type":"callout","text":"Josué 2","body":"Rahab recibe a los mensajeros israelitas, los esconde, pide misericordia para su familia y recibe la instrucción de colocar un cordón escarlata en su ventana y mantener a su familia dentro."},{"type":"field","text":"Primero, resume lo que sucede en la historia sin añadir simbolismo ni aplicación.","id":"f_75f8039ff10695"},{"type":"field","text":"¿Dónde ve la lección en video una conexión centrada en Cristo en esta historia? Enumera los detalles que utiliza.","id":"f_a0cf5b77555ac1"},{"type":"field","text":"¿Dónde estoy yo en esta historia? ¿Qué persona, decisión o respuesta me desafía más personalmente?","id":"f_deb73a5c386b5a"},{"type":"heading","text":"Usa las perspectivas de la lección"},{"type":"field","id":"f_6ae77be19f643d","text":"¿Dónde está Cristo?"},{"type":"field","id":"f_9412fdf0960cd1","text":"¿Dónde estoy yo?"},{"type":"field","id":"f_110b006f4bc442","text":"¿Qué muestra esto acerca del carácter de Dios?"},{"type":"field","id":"f_91d96f1d687550","text":"¿Qué hay de redentor aquí?"},{"type":"field","id":"f_3f88cb166759ef","text":"¿Qué muestra esto acerca de la iglesia?"},{"type":"field","id":"f_d767af6b4d5bd3","text":"¿Qué significa esto en mi vida?"},{"type":"field","text":"Escribe una oración que exprese la lección central enfocada en Cristo que compartirías con otra persona.","id":"f_99746ce53b67e5"},{"type":"heading","text":"3. Tu turno"},{"type":"callout","text":"Génesis 22","body":"A Abraham se le dice que ofrezca a Isaac. Isaac es colocado sobre el altar y se provee un carnero en su lugar. La lección menciona esta historia como otro ejemplo para buscar a Cristo."},{"type":"field","text":"¿Qué sucede en la historia a simple vista? Mantén esto separado del simbolismo.","id":"f_83542796e66966"},{"type":"field","text":"¿Hacia dónde podría dirigirte el método «Busca a Cristo» de la lección en esta historia?","id":"f_11e18799682832"},{"type":"field","text":"¿Qué detalles respaldan esa conexión?","id":"f_ac3692e201714e"},{"type":"field","text":"¿Dónde estás tú en la historia? ¿Qué respuesta personal te invita a dar el pasaje?","id":"f_25266e1a1ea771"},{"type":"field","text":"¿Qué te muestra este pasaje acerca del carácter de Dios y la redención?","id":"f_986688a59c6a91"},{"type":"field","text":"Escribe una reflexión devocional de 3 oraciones a partir de tu estudio.","id":"f_68df2fd1d5d646"},{"type":"heading","text":"4. Hazlo parte de tu estudio bíblico"},{"type":"field","text":"Lo más importante que aprendí de este video fue:","id":"f_67d0ae6a24039b"},{"type":"field","text":"Un error o mal hábito que este método puede ayudarme a evitar es:","id":"f_e071fa94425cbb"},{"type":"field","text":"Un pasaje que quiero estudiar con este método esta semana es:","id":"f_81908514acf4f4"},{"type":"heading","text":"Mi comprobación de estudio centrado en Cristo"},{"type":"check","id":"f_74e5eca048088b","text":"Primero comprendí lo que sucede en el pasaje."},{"type":"check","id":"f_7546c23932b574","text":"Pregunté dónde puede verse o reflejarse a Cristo."},{"type":"check","id":"f_208a0e5ab01e42","text":"Identifiqué qué detalles respaldan la conexión."},{"type":"check","id":"f_e563dd9026cef9","text":"Pregunté dónde estoy yo en la historia."},{"type":"check","id":"f_64f1d376b75edb","text":"Avancé hacia la relación y la aplicación, no solo hacia el simbolismo."},{"type":"field","text":"Mi próxima acción dentro de las próximas 24 horas:","id":"f_78619d0ca1709b"},{"type":"heading","text":"5. Observaciones de ejemplo de la lección en video"},{"type":"text","text":"Estas son observaciones de ejemplo tomadas de la lección en video. No pretenden reemplazar tu propio estudio cuidadoso del pasaje."},{"type":"text","text":"• En Josué 2, Rahab recibe a dos mensajeros, se entera de que viene destrucción y recibe una vía de escape."},{"type":"text","text":"• El cordón escarlata puede usarse devocionalmente como una conexión centrada en Cristo porque la lección relaciona el cordón rojo con la sangre, la vida y la muerte de Jesús."},{"type":"text","text":"• La lección también invita al lector a identificarse con Rahab: ella recibe el mensaje, se lo cuenta a su familia e invita a otros a entrar en el lugar de seguridad."},{"type":"text","text":"• La lección compara la casa de Rahab con otras historias de «permanece con quien salva», como el arca de Noé y permanecer con Jesús."},{"type":"text","text":"• El objetivo no es simplemente encontrar símbolos. La lección vuelve repetidamente a la pregunta personal: ¿Estoy permaneciendo con Jesús y compartiéndolo con otros?"},{"type":"heading","text":"Tu resumen final"},{"type":"field","text":"Explica este método de Bible Decoded a un amigo en 3 a 5 oraciones.","id":"f_8e590506b167b7"},{"type":"field","text":"Escribe una pregunta que todavía tengas después de completar este cuaderno.","id":"f_e9d06108c25492"},{"type":"text","text":"No te apresures al siguiente método. Usa primero este método con un pasaje real. La habilidad crece con la práctica."}]')
ON CONFLICT(id) DO UPDATE SET
  blocks=excluded.blocks,
  updated_at=strftime('%Y-%m-%dT%H:%M:%fZ','now');

INSERT INTO bd_content(id, blocks)
VALUES ('es:pattern-recognition', '[{"type":"field","id":"f_1d7a16681fecd2","text":"Nombre","short":true},{"type":"field","id":"f_bfe72cfd45744a","text":"Fecha de inicio","short":true},{"type":"heading","text":"Actitud para estudiar con Bible Decoded"},{"type":"text","text":"El Video 1 estableció cuatro preguntas que conviene tener presentes al usar cada método de Bible Decoded."},{"type":"heading","text":"Mantén contigo estas cuatro preguntas"},{"type":"check","id":"f_0e2a8d74dfe2cc","text":"Ora por la guía del Espíritu Santo."},{"type":"check","id":"f_da581705667b35","text":"Pregunta: ¿Qué me dice esto acerca del carácter de Dios?"},{"type":"check","id":"f_3608e3f37fe109","text":"Pregunta: ¿De qué manera esto es redentor?"},{"type":"check","id":"f_3cc1aafb293370","text":"Pregunta: ¿Qué significa esto en mi vida?"},{"type":"text","text":"La lección introductoria también advierte que las herramientas de estudio pueden usarse mal. Explora con libertad, pero sigue comprobando tus conclusiones con el pasaje y su contexto."},{"type":"field","text":"¿Qué es lo que más quieres que este método te ayude a ver o comprender?","id":"f_b867d40fed495d"},{"type":"heading","text":"1. Aprende el método"},{"type":"text","text":"Al terminar este cuaderno, deberías poder:"},{"type":"check","id":"f_c66a8c85e09208","text":"Divide un pasaje bíblico en una secuencia sencilla de acontecimientos o ideas."},{"type":"check","id":"f_83c151f3cabfe3","text":"Compara esa secuencia con otro pasaje."},{"type":"check","id":"f_58c4e8bf367bf3","text":"Reconoce cuándo los pasos repetidos forman un patrón significativo."},{"type":"check","id":"f_2b76da07ba937c","text":"Pregunta qué significa el patrón y cómo se aplica personalmente."},{"type":"check","id":"f_67f29f3bc37a50","text":"Usa los acontecimientos cronológicos como una pista al buscar patrones."},{"type":"heading","text":"El método de un vistazo"},{"type":"text","text":"Paso 1"},{"type":"text","text":"Lee el pasaje y divídelo en una secuencia breve."},{"type":"text","text":"Paso 2"},{"type":"text","text":"Busca la misma secuencia en otro lugar de la Biblia."},{"type":"text","text":"Paso 3"},{"type":"text","text":"Compara lo que es igual, lo que es diferente y lo que puede estar implícito."},{"type":"text","text":"Paso 4"},{"type":"text","text":"Pregunta: ¿Qué significa este patrón?"},{"type":"text","text":"Paso 5"},{"type":"text","text":"Pregunta: ¿Cómo se aplica esto a mi vida?"},{"type":"field","text":"En tus propias palabras, ¿cuál es la habilidad principal que enseña este video?","id":"f_d9e0bcd7a32d42"},{"type":"field","text":"¿Qué parte del método te resulta más fácil? ¿Cuál te resulta más difícil?","id":"f_6a9587b7479e26"},{"type":"heading","text":"2. Práctica guiada"},{"type":"callout","text":"Isaías 6:1-8","body":"Isaías ve al Señor, toma conciencia de su propia impureza, recibe purificación y responde al llamado de Dios: «Heme aquí, envíame a mí»."},{"type":"heading","text":"Divide Isaías 6 en pasos"},{"type":"field","text":"Paso 1:","id":"f_f33b37f92b4a43"},{"type":"field","text":"Paso 2:","id":"f_7829656a162f72"},{"type":"field","text":"Paso 3:","id":"f_3952c583466850"},{"type":"field","text":"Paso 4:","id":"f_cce59e84fc7825"},{"type":"field","text":"Paso 5:","id":"f_9139fe9a2a8882"},{"type":"callout","text":"Lucas 5:4-11","body":"Pedro presencia la pesca milagrosa, reconoce su pecaminosidad y Jesús lo llama a convertirse en pescador de personas."},{"type":"field","text":"Ahora divide Lucas 5 en pasos. ¿Qué pasos coinciden con Isaías 6?","id":"f_a115436c753537"},{"type":"field","text":"¿Qué paso es explícito en un pasaje pero solo está implícito en el otro?","id":"f_46188b34990f5e"},{"type":"field","text":"¿Cómo llama la lección en video a este patrón repetido?","id":"f_d02e23d9c239cb"},{"type":"field","text":"¿Cómo desafía o describe este patrón tu propia experiencia con Jesús?","id":"f_7cac3500a2281e"},{"type":"heading","text":"3. Tu turno"},{"type":"callout","text":"Génesis 24, Génesis 29 y la historia de Moisés junto a un pozo","body":"La lección compara historias repetidas junto a pozos que incluyen viaje o misión, sacar agua, hospitalidad, trabajo arduo y matrimonio."},{"type":"grid","columns":["Elemento del patrón","Moisés","Rebeca / Isaac","Jacob / Raquel"],"rows":[{"label":"Misión/viaje","cells":[{"id":"f_cdafa378c5b6da","type":"field","text":"Misión/viaje — Moisés"},{"id":"f_2cda45a25a2ff8","type":"field","text":"Misión/viaje — Rebeca / Isaac"},{"id":"f_5ec559861dc5ea","type":"field","text":"Misión/viaje — Jacob / Raquel"}]},{"label":"Pozo/agua","cells":[{"id":"f_f1b4abff06d2a3","type":"field","text":"Pozo/agua — Moisés"},{"id":"f_7ba42e7d30b077","type":"field","text":"Pozo/agua — Rebeca / Isaac"},{"id":"f_db4e4c2a7e99da","type":"field","text":"Pozo/agua — Jacob / Raquel"}]},{"label":"Trabajo","cells":[{"id":"f_020d26b5cb9af3","type":"field","text":"Trabajo — Moisés"},{"id":"f_5586abf9712412","type":"field","text":"Trabajo — Rebeca / Isaac"},{"id":"f_bfa651964f1907","type":"field","text":"Trabajo — Jacob / Raquel"}]},{"label":"Hospitalidad","cells":[{"id":"f_313f02f3b953f5","type":"field","text":"Hospitalidad — Moisés"},{"id":"f_b68283a4ce59e0","type":"field","text":"Hospitalidad — Rebeca / Isaac"},{"id":"f_990ccf723701af","type":"field","text":"Hospitalidad — Jacob / Raquel"}]}]},{"type":"field","text":"¿Qué secuencia repetida ves a lo largo de estas historias?","id":"f_f4a692c238a01b"},{"type":"field","text":"¿Qué lección extrae el video de este patrón?","id":"f_300ca42e63081a"},{"type":"field","text":"¿Qué partes son observaciones directas de las historias y cuáles son aplicación?","id":"f_3289fe6f2aa112"},{"type":"field","text":"Piensa en otra secuencia repetida en las Escrituras. Enumera los pasajes y los pasos que crees que se repiten.","id":"f_7d533f7716be98"},{"type":"heading","text":"4. Hazlo parte de tu estudio bíblico"},{"type":"field","text":"Lo más importante que aprendí de este video fue:","id":"f_235a8f14ee7dd1"},{"type":"field","text":"Un error o mal hábito que este método puede ayudarme a evitar es:","id":"f_0002aca7fa9f46"},{"type":"field","text":"Un pasaje que quiero estudiar con este método esta semana es:","id":"f_9db2b348ca9d39"},{"type":"heading","text":"Mi comprobación de patrones"},{"type":"check","id":"f_19f9cc59ab6288","text":"Dividí el primer pasaje en pasos."},{"type":"check","id":"f_7c9d90f7eca7a2","text":"Encontré otro pasaje con una secuencia semejante."},{"type":"check","id":"f_a78250247e1d63","text":"Anoté tanto las semejanzas como las diferencias."},{"type":"check","id":"f_ad9afe849b36ac","text":"Pregunté qué podría significar el patrón repetido."},{"type":"check","id":"f_b78e6f4e2efd1f","text":"Separé la observación de la aplicación."},{"type":"field","text":"Mi próxima acción dentro de las próximas 24 horas:","id":"f_0faf0039b97b00"},{"type":"heading","text":"5. Observaciones de ejemplo de la lección en video"},{"type":"text","text":"Estas son observaciones de ejemplo tomadas de la lección en video. No pretenden reemplazar tu propio estudio cuidadoso del pasaje."},{"type":"text","text":"• La lección divide Isaías 6 en una secuencia de conversión: ver la gloria/el carácter de Dios, reconocer la propia pecaminosidad, recibir purificación y ser enviado con el mensaje de Dios."},{"type":"text","text":"• Lucas 5 sigue un movimiento parecido: Pedro presencia la obra de Jesús, reconoce su pecaminosidad y es llamado a convertirse en pescador de personas."},{"type":"text","text":"• La lección identifica esto como un patrón de conversión y luego invita al lector a compararlo con su experiencia personal."},{"type":"text","text":"• Un segundo patrón usa historias junto a pozos relacionadas con Moisés, Rebeca/Isaac y Jacob/Raquel: viaje o misión, un pozo, una mujer trabajadora y hospitalaria y, finalmente, matrimonio."},{"type":"text","text":"• El método es sencillo: divide el pasaje en pasos y luego busca esos mismos pasos en otros lugares."},{"type":"heading","text":"Tu resumen final"},{"type":"field","text":"Explica este método de Bible Decoded a un amigo en 3 a 5 oraciones.","id":"f_8ffcc525778415"},{"type":"field","text":"Escribe una pregunta que todavía tengas después de completar este cuaderno.","id":"f_29c9463a52d056"},{"type":"text","text":"No te apresures al siguiente método. Usa primero este método con un pasaje real. La habilidad crece con la práctica."}]')
ON CONFLICT(id) DO UPDATE SET
  blocks=excluded.blocks,
  updated_at=strftime('%Y-%m-%dT%H:%M:%fZ','now');

INSERT INTO bd_content(id, blocks)
VALUES ('es:questioning-method', '[{"type":"field","id":"f_508468f7ec47b6","text":"Nombre","short":true},{"type":"field","id":"f_86218f530ad52e","text":"Fecha de inicio","short":true},{"type":"heading","text":"Actitud para estudiar con Bible Decoded"},{"type":"text","text":"El Video 1 estableció cuatro preguntas que conviene tener presentes al usar cada método de Bible Decoded."},{"type":"heading","text":"Mantén contigo estas cuatro preguntas"},{"type":"check","id":"f_d5bdc299e1be92","text":"Ora por la guía del Espíritu Santo."},{"type":"check","id":"f_0075c8275e32f8","text":"Pregunta: ¿Qué me dice esto acerca del carácter de Dios?"},{"type":"check","id":"f_7273410c45aad8","text":"Pregunta: ¿De qué manera esto es redentor?"},{"type":"check","id":"f_c2139c87019036","text":"Pregunta: ¿Qué significa esto en mi vida?"},{"type":"text","text":"La lección introductoria también advierte que las herramientas de estudio pueden usarse mal. Explora con libertad, pero sigue comprobando tus conclusiones con el pasaje y su contexto."},{"type":"field","text":"¿Qué es lo que más quieres que este método te ayude a ver o comprender?","id":"f_c531f50c256726"},{"type":"heading","text":"1. Aprende el método"},{"type":"text","text":"Al terminar este cuaderno, deberías poder:"},{"type":"check","id":"f_255f52c2203ac1","text":"Haz las seis preguntas básicas de investigación de un pasaje bíblico."},{"type":"check","id":"f_e20c47ce1d5afb","text":"Investiga las personas, lugares, nombres y detalles de contexto mencionados en el texto."},{"type":"check","id":"f_77ff5080775b66","text":"Haz preguntas de seguimiento en lugar de detenerte en la primera respuesta."},{"type":"check","id":"f_42850bb235fde1","text":"Conecta tus descubrimientos con otros métodos de Bible Decoded, como los patrones y la búsqueda de Cristo."},{"type":"check","id":"f_98447f840c1a13","text":"Pasa de la información a la pregunta: ¿Qué significa esto en mi vida?"},{"type":"heading","text":"El método de un vistazo"},{"type":"text","text":"¿Quién?"},{"type":"text","text":"¿Quién habla, actúa, escucha, se opone, ayuda o resulta afectado?"},{"type":"text","text":"¿Qué?"},{"type":"text","text":"¿Qué sucede realmente? ¿Qué palabras, acciones, objetos o conflictos son importantes?"},{"type":"text","text":"¿Cuándo?"},{"type":"text","text":"¿Cuándo sucede esto en la historia y en la línea de tiempo bíblica más amplia?"},{"type":"text","text":"¿Dónde?"},{"type":"text","text":"¿Dónde sucede? ¿Qué sabemos acerca de ese lugar?"},{"type":"text","text":"¿Por qué?"},{"type":"text","text":"¿Por qué actúan así las personas? ¿Por qué se incluye este detalle?"},{"type":"text","text":"¿Cómo?"},{"type":"text","text":"¿Cómo se desarrolla el acontecimiento? ¿Cómo se resuelve el problema? ¿Cómo se aplica?"},{"type":"field","text":"En tus propias palabras, ¿cuál es la habilidad principal que enseña este video?","id":"f_1573d5f932f7ab"},{"type":"field","text":"¿Qué parte del método te resulta más fácil? ¿Cuál te resulta más difícil?","id":"f_776b2d2785d8e0"},{"type":"heading","text":"2. Práctica guiada"},{"type":"callout","text":"1 Samuel 17","body":"David llega al campo de batalla entre Israel y los filisteos y finalmente se enfrenta a Goliat."},{"type":"heading","text":"Haz las seis preguntas"},{"type":"field","id":"f_218ba74f147399","text":"¿QUIÉN? Identifica a las personas y grupos."},{"type":"field","id":"f_d0afc73793dbc6","text":"¿QUÉ? ¿Qué conflicto o problema está ocurriendo?"},{"type":"field","id":"f_bf188ac2545bb8","text":"¿CUÁNDO? ¿Qué está sucediendo en la historia más amplia de Israel?"},{"type":"field","id":"f_051153f98d4f04","text":"¿DÓNDE? ¿Qué lugares se mencionan?"},{"type":"field","id":"f_df6a4bc8ca825e","text":"¿POR QUÉ? ¿Por qué ocurre el conflicto? ¿Por qué responde David de esa manera?"},{"type":"field","id":"f_80e93ebf0e7db9","text":"¿CÓMO? ¿Cómo se resuelve finalmente el problema?"},{"type":"field","text":"Elige un nombre o lugar del pasaje que merezca más investigación. ¿Qué buscarías?","id":"f_dea3276aec7c52"},{"type":"field","text":"Escribe tres preguntas de seguimiento que surgieron después de responder las primeras seis.","id":"f_e543cefb80b31b"},{"type":"field","text":"¿Cómo podrían «¿Dónde está Cristo?» o «¿Qué patrón veo?» profundizar este mismo pasaje?","id":"f_1cf08d4f19261f"},{"type":"heading","text":"3. Tu turno"},{"type":"callout","text":"Josué 2","body":"Usa el método de las preguntas con la historia de Rahab sin volver a mirar las notas del video hasta que termines."},{"type":"field","id":"f_df019eef79742a","text":"¿QUIÉN?"},{"type":"field","id":"f_99aa636416a04e","text":"¿QUÉ?"},{"type":"field","id":"f_3d2a8edd9edc4d","text":"¿CUÁNDO?"},{"type":"field","id":"f_9f97a1c045fcc2","text":"¿DÓNDE?"},{"type":"field","id":"f_9e7d0949ba7e0b","text":"¿POR QUÉ?"},{"type":"field","id":"f_73fa92d025c379","text":"¿CÓMO?"},{"type":"field","text":"¿Qué respuesta produjo la nueva pregunta más interesante?","id":"f_1fde2b84ee5f4a"},{"type":"field","text":"Escribe cinco preguntas de seguimiento que requieran más lectura bíblica o investigación.","id":"f_78741516de643c"},{"type":"field","text":"¿Qué método de Bible Decoded combinarías después con el método de las preguntas? ¿Por qué?","id":"f_57cabcf236ab5e"},{"type":"field","text":"¿Qué significa este estudio en tu vida?","id":"f_bc53da52f40288"},{"type":"heading","text":"4. Hazlo parte de tu estudio bíblico"},{"type":"field","text":"Lo más importante que aprendí de este video fue:","id":"f_e221743d621ea4"},{"type":"field","text":"Un error o mal hábito que este método puede ayudarme a evitar es:","id":"f_dc22c644698f8a"},{"type":"field","text":"Un pasaje que quiero estudiar con este método esta semana es:","id":"f_a3afdb0a25ae90"},{"type":"heading","text":"Mi comprobación del método de las preguntas"},{"type":"check","id":"f_fdf6780a530556","text":"Pregunté Quién, Qué, Cuándo, Dónde, Por qué y Cómo."},{"type":"check","id":"f_8cfbe83211c874","text":"Escribí preguntas de seguimiento en lugar de detenerme en respuestas rápidas."},{"type":"check","id":"f_52914199b618b4","text":"Investigué nombres, lugares y detalles importantes."},{"type":"check","id":"f_6341e92052b86d","text":"Conecté los hechos con otro método de Bible Decoded."},{"type":"check","id":"f_c849e61474adba","text":"Pregunté qué significa el estudio en mi vida."},{"type":"field","text":"Mi próxima acción dentro de las próximas 24 horas:","id":"f_8100349b8ecd29"},{"type":"heading","text":"5. Observaciones de ejemplo de la lección en video"},{"type":"text","text":"Estas son observaciones de ejemplo tomadas de la lección en video. No pretenden reemplazar tu propio estudio cuidadoso del pasaje."},{"type":"text","text":"• La lección ilustra el método con David y Goliat al hacer preguntas sobre lugares como Soco, Azeca y Efes-damim, y sobre nombres como Goliat."},{"type":"text","text":"• El ejemplo de Rahab pregunta quiénes participaron, qué quería Josué, cuándo ocurrió el acontecimiento en relación con el Éxodo y los años en el desierto, dónde estaba Jericó, por qué Israel estaba allí y cómo finalmente fue tomada la ciudad."},{"type":"text","text":"• Luego la lección sigue haciendo preguntas de seguimiento desde el punto de vista de Rahab, en lugar de detenerse con el primer conjunto de datos."},{"type":"text","text":"• El método de las preguntas abre naturalmente la puerta a otros métodos: el estudio de Rahab pasa a «¿Dónde está Cristo?» y al reconocimiento de patrones."},{"type":"text","text":"• El último paso es personal: después de que las preguntas revelan detalles, pregunta qué significan esos detalles para tu propia vida."},{"type":"heading","text":"Tu resumen final"},{"type":"field","text":"Explica este método de Bible Decoded a un amigo en 3 a 5 oraciones.","id":"f_3be88892239d12"},{"type":"field","text":"Escribe una pregunta que todavía tengas después de completar este cuaderno.","id":"f_4e9365b0c9dbac"},{"type":"text","text":"No te apresures al siguiente método. Usa primero este método con un pasaje real. La habilidad crece con la práctica."}]')
ON CONFLICT(id) DO UPDATE SET
  blocks=excluded.blocks,
  updated_at=strftime('%Y-%m-%dT%H:%M:%fZ','now');

INSERT INTO bd_content(id, blocks)
VALUES ('es:exegesis', '[{"type":"field","id":"f_fa258eb2ce6603","text":"Nombre","short":true},{"type":"field","id":"f_0a8aa0a56882f3","text":"Fecha de inicio","short":true},{"type":"heading","text":"Actitud para estudiar con Bible Decoded"},{"type":"text","text":"El Video 1 estableció cuatro preguntas que conviene tener presentes al usar cada método de Bible Decoded."},{"type":"heading","text":"Mantén contigo estas cuatro preguntas"},{"type":"check","id":"f_3eb9b27bfa9e4a","text":"Ora por la guía del Espíritu Santo."},{"type":"check","id":"f_5367f79f5033f7","text":"Pregunta: ¿Qué me dice esto acerca del carácter de Dios?"},{"type":"check","id":"f_240ac8f7af58d5","text":"Pregunta: ¿De qué manera esto es redentor?"},{"type":"check","id":"f_8f62643329acf7","text":"Pregunta: ¿Qué significa esto en mi vida?"},{"type":"text","text":"La lección introductoria también advierte que las herramientas de estudio pueden usarse mal. Explora con libertad, pero sigue comprobando tus conclusiones con el pasaje y su contexto."},{"type":"field","text":"¿Qué es lo que más quieres que este método te ayude a ver o comprender?","id":"f_ccd124c1fc9016"},{"type":"heading","text":"1. Aprende el método"},{"type":"text","text":"Al terminar este cuaderno, deberías poder:"},{"type":"check","id":"f_f8d9d19fde6ff6","text":"Explica la diferencia entre exégesis y eiségesis tal como se enseña en la lección."},{"type":"check","id":"f_6644efb85a1b12","text":"Estudia el contexto histórico, literario y bíblico antes de formar conclusiones."},{"type":"check","id":"f_c4eace7f60f014","text":"Considera el género, las palabras clave, el trasfondo cultural y las referencias cruzadas."},{"type":"check","id":"f_718e237d7af4e2","text":"Identifica el mensaje que el autor pretendía comunicar antes de pasar a la aplicación personal."},{"type":"check","id":"f_eb8317456ebfef","text":"Usa la humildad y el contexto como salvaguardas contra la mala interpretación."},{"type":"heading","text":"El método de un vistazo"},{"type":"text","text":"Exégesis"},{"type":"text","text":"Pregunta qué pretendía comunicar el escritor y extrae del pasaje su significado."},{"type":"text","text":"Eiségesis"},{"type":"text","text":"Introducir tus propias ideas o suposiciones en el pasaje."},{"type":"text","text":"Primero el contexto"},{"type":"text","text":"¿Quién lo escribió? ¿Cuándo? ¿A quién? ¿Qué viene antes y después? ¿Cómo encaja con toda la Biblia?"},{"type":"text","text":"Estudia los detalles"},{"type":"text","text":"Palabras en el idioma original cuando sean útiles, género literario, cultura, teología, referencias cruzadas y recursos de estudio confiables."},{"type":"text","text":"Luego aplica"},{"type":"text","text":"Después de comprender el pasaje en contexto, pregunta cómo se aplica el principio a la fe y a la vida de hoy."},{"type":"field","text":"En tus propias palabras, ¿cuál es la habilidad principal que enseña este video?","id":"f_6efcaa7a79fd8d"},{"type":"field","text":"¿Qué parte del método te resulta más fácil? ¿Cuál te resulta más difícil?","id":"f_d45c633927195b"},{"type":"heading","text":"2. Práctica guiada"},{"type":"callout","text":"Mateo 24:14","body":"«Este evangelio del reino» es predicado en todo el mundo antes de que venga «el fin». La lección usa este versículo como un ejemplo breve de exégesis."},{"type":"field","text":"Contexto histórico: ¿Quién habla? ¿A quién? ¿Qué tema más amplio se está tratando?","id":"f_434e6eb4e0b4f3"},{"type":"field","text":"Contexto literario: ¿Qué viene antes y después de este versículo?","id":"f_a88636e410806f"},{"type":"field","text":"Palabra clave: ¿Qué palabra importante estudiarías con más cuidado?","id":"f_d35c545d446d1d"},{"type":"field","text":"Género: ¿Qué tipo de material bíblico es esta sección?","id":"f_febf96e8988963"},{"type":"field","text":"Contexto bíblico: ¿Qué otros pasajes podrían ayudarte a comprender este tema?","id":"f_133d9dc29db1a1"},{"type":"field","text":"Mensaje pretendido por el autor/hablante: ¿Qué comunica el pasaje antes de que lo apliques personalmente?","id":"f_d1d98270e0ecbc"},{"type":"field","text":"Aplicación: ¿Qué principio puedes llevar a tu vida hoy?","id":"f_4a623955591895"},{"type":"heading","text":"Comprobación de exégesis"},{"type":"check","id":"f_11a139f10fb335","text":"Observé lo que viene antes y después del versículo."},{"type":"check","id":"f_e6434fe6dfcc71","text":"Consideré la audiencia y la situación originales."},{"type":"check","id":"f_1b534268ba538d","text":"No comencé con la conclusión que quería demostrar."},{"type":"check","id":"f_e48b309d96489d","text":"Comparé el pasaje con otras Escrituras."},{"type":"check","id":"f_7b27571132d0e2","text":"Separé el significado del pasaje de mi aplicación personal."},{"type":"heading","text":"3. Tu turno"},{"type":"callout","text":"Lucas 16:19-31","body":"El rico y Lázaro. El video usa este pasaje para demostrar por qué importan el contexto, el género, los términos clave, las referencias cruzadas y la intención del autor."},{"type":"field","text":"¿Qué está sucediendo en Lucas 16 inmediatamente antes de esta historia?","id":"f_af6c0d6caabcc3"},{"type":"field","text":"¿A quién se dirige Jesús en la sección que rodea esta historia?","id":"f_0b7f43b8c1430a"},{"type":"field","text":"¿Qué género identifica la lección para esta historia?","id":"f_cf370571c70ff6"},{"type":"field","text":"¿Qué palabras o imágenes requieren un estudio cuidadoso?","id":"f_636beb1e7d857d"},{"type":"field","text":"¿Qué referencias cruzadas usa la lección para comparar la enseñanza bíblica acerca de la muerte?","id":"f_93285acb6d962f"},{"type":"field","text":"¿Qué problema moral o teológico dice la lección que Jesús está confrontando?","id":"f_98982e2762ac45"},{"type":"field","text":"Escribe el mensaje principal del pasaje en una oración antes de hacer una aplicación personal.","id":"f_b182ba773a9d73"},{"type":"field","text":"Ahora escribe una aplicación personal.","id":"f_d89ec8d7ead75c"},{"type":"heading","text":"4. Hazlo parte de tu estudio bíblico"},{"type":"field","text":"Lo más importante que aprendí de este video fue:","id":"f_f482a08e690f43"},{"type":"field","text":"Un error o mal hábito que este método puede ayudarme a evitar es:","id":"f_3ef53ecee40415"},{"type":"field","text":"Un pasaje que quiero estudiar con este método esta semana es:","id":"f_9b39df6727b429"},{"type":"heading","text":"Mi comprobación de exégesis"},{"type":"check","id":"f_f8b64854e58650","text":"Estudié el contexto inmediato y el contexto más amplio."},{"type":"check","id":"f_67ac5fabfe9b33","text":"Consideré la audiencia y la situación originales."},{"type":"check","id":"f_ada1fadaa6f1ab","text":"Identifiqué el género."},{"type":"check","id":"f_00f12cec28ac61","text":"Examiné palabras clave y referencias cruzadas."},{"type":"check","id":"f_5a8bef8b88adbe","text":"Pregunté qué pretendía comunicar el escritor antes de preguntar qué significa para mí."},{"type":"field","text":"Mi próxima acción dentro de las próximas 24 horas:","id":"f_dec211040c6f5c"},{"type":"heading","text":"5. Observaciones de ejemplo de la lección en video"},{"type":"text","text":"Estas son observaciones de ejemplo tomadas de la lección en video. No pretenden reemplazar tu propio estudio cuidadoso del pasaje."},{"type":"text","text":"• La lección presenta un proceso de exégesis de nueve pasos: elegir un pasaje, comprender el contexto, estudiar el idioma original cuando sea útil, identificar el género, examinar el trasfondo, comparar las Escrituras, consultar fuentes confiables, determinar la intención del autor y aplicar el mensaje."},{"type":"text","text":"• Mateo 24:14 se usa como un ejemplo breve que incluye contexto histórico, contexto literario, la palabra «evangelio», implicación teológica y aplicación."},{"type":"text","text":"• Lucas 16:19-31 se usa como un ejemplo extenso para mostrar por qué el contexto, el género, el estudio de palabras, los temas y las referencias cruzadas importan antes de llegar a conclusiones."},{"type":"text","text":"• La lección usa a Harold Camping como una historia de advertencia sobre las consecuencias de una mala interpretación y enfatiza la humildad y la fidelidad al texto."},{"type":"text","text":"• La disciplina central es preguntar primero: «¿Qué pretendía comunicar el escritor?» antes de preguntar: «¿Qué significa esto para mí?»."},{"type":"heading","text":"Tu resumen final"},{"type":"field","text":"Explica este método de Bible Decoded a un amigo en 3 a 5 oraciones.","id":"f_06417dcb800879"},{"type":"field","text":"Escribe una pregunta que todavía tengas después de completar este cuaderno.","id":"f_af994f6a0666b9"},{"type":"text","text":"No te apresures al siguiente método. Usa primero este método con un pasaje real. La habilidad crece con la práctica."}]')
ON CONFLICT(id) DO UPDATE SET
  blocks=excluded.blocks,
  updated_at=strftime('%Y-%m-%dT%H:%M:%fZ','now');

INSERT INTO bd_content(id, blocks)
VALUES ('es:bible-memorization', '[{"type":"field","id":"f_d97c92fb1cca67","text":"Nombre","short":true},{"type":"field","id":"f_3117a0beece92e","text":"Fecha de inicio","short":true},{"type":"heading","text":"Actitud para estudiar con Bible Decoded"},{"type":"text","text":"El Video 1 estableció cuatro preguntas que conviene tener presentes al usar cada método de Bible Decoded."},{"type":"heading","text":"Mantén contigo estas cuatro preguntas"},{"type":"check","id":"f_cd27d06094a176","text":"Ora por la guía del Espíritu Santo."},{"type":"check","id":"f_d686c1f721dc5d","text":"Pregunta: ¿Qué me dice esto acerca del carácter de Dios?"},{"type":"check","id":"f_5b8cdd66b4cfc9","text":"Pregunta: ¿De qué manera esto es redentor?"},{"type":"check","id":"f_8955cca426bc52","text":"Pregunta: ¿Qué significa esto en mi vida?"},{"type":"text","text":"La lección introductoria también advierte que las herramientas de estudio pueden usarse mal. Explora con libertad, pero sigue comprobando tus conclusiones con el pasaje y su contexto."},{"type":"field","text":"¿Qué es lo que más quieres que este método te ayude a ver o comprender?","id":"f_cf64c3df72254c"},{"type":"heading","text":"1. Aprende el método"},{"type":"text","text":"Al terminar este cuaderno, deberías poder:"},{"type":"check","id":"f_eba5828440503c","text":"Explica por qué la lección presenta la memorización como un recurso espiritual para la vida diaria y la tentación."},{"type":"check","id":"f_829b0939ab1897","text":"Usa la repetición para fortalecer la memoria."},{"type":"check","id":"f_0442d0135b61a2","text":"Enfatiza cada palabra de un versículo para ir más despacio y notar su significado."},{"type":"check","id":"f_ad8a81e8613b58","text":"Memoriza capítulos o pasajes conectados en lugar de solo versículos aislados."},{"type":"check","id":"f_ce0658d5fae6e5","text":"Construye un mapa mental sencillo de capítulos y temas de la Biblia."},{"type":"heading","text":"El método de un vistazo"},{"type":"text","text":"Repetición"},{"type":"text","text":"Lee el pasaje en voz alta y repítelo en secciones pequeñas hasta que recordarlo resulte más fácil."},{"type":"text","text":"Enfatiza cada palabra"},{"type":"text","text":"Repite el versículo enfatizando una palabra diferente cada vez para notar más significado."},{"type":"text","text":"Aprende capítulos"},{"type":"text","text":"La lección anima a memorizar secciones conectadas más amplias en lugar de solo versículos dispersos."},{"type":"text","text":"Aprende los temas de los capítulos"},{"type":"text","text":"Conoce el tema básico de los capítulos para recordar la historia bíblica más amplia y su contexto."},{"type":"text","text":"Usa canciones"},{"type":"text","text":"Las canciones basadas en las Escrituras pueden ayudar a guardar las palabras en la memoria a largo plazo."},{"type":"field","text":"En tus propias palabras, ¿cuál es la habilidad principal que enseña este video?","id":"f_236f5c762d1bbb"},{"type":"field","text":"¿Qué parte del método te resulta más fácil? ¿Cuál te resulta más difícil?","id":"f_f6285103ac4be0"},{"type":"heading","text":"2. Práctica guiada"},{"type":"callout","text":"Proverbios 3:5-6","body":"La lección usa este pasaje como ejemplo de repetición y fortalecimiento de la memoria."},{"type":"field","text":"Escribe Proverbios 3:5-6 según la traducción bíblica que estás usando.","id":"f_84fda39e7a5402"},{"type":"field","text":"Divide el pasaje en secciones pequeñas que puedas repetir en voz alta.","id":"f_63f160568625d2"},{"type":"field","text":"¿Qué palabras enfatizarás una por una? ¿Qué detalle nuevo notas al ir más despacio?","id":"f_f80ae3232e275c"},{"type":"field","text":"Cierra tu Biblia y escribe todo lo que puedas recordar del pasaje.","id":"f_0c3ec51634949d"},{"type":"field","text":"Revisa tu intento. ¿Qué palabras o frases omitiste?","id":"f_f8ff4633a572ef"},{"type":"field","text":"Escribe el pasaje una vez más de memoria.","id":"f_9b3d24802f99c9"},{"type":"heading","text":"3. Tu turno"},{"type":"callout","text":"Juan 1:1","body":"La lección recomienda enfatizar cada palabra para ir más despacio y observar el versículo con mayor cuidado."},{"type":"field","text":"Escribe Juan 1:1.","id":"f_88312d9570547a"},{"type":"field","text":"Repite el versículo varias veces, enfatizando una palabra diferente cada vez. Anota tres observaciones que te llamaron la atención.","id":"f_4d7357386fdb0d"},{"type":"callout","text":"Desafío de memorización de un capítulo","body":"Elige un capítulo bíblico corto o un párrafo conectado que quieras memorizar."},{"type":"field","text":"Pasaje/capítulo elegido:","id":"f_c0d60c8d601258"},{"type":"field","text":"¿Por qué lo elegiste?","id":"f_7ece1a0bcbe92e"},{"type":"field","text":"Divídelo en 3 a 5 secciones para memorizar.","id":"f_b350c6c78b5e61"},{"type":"field","text":"Escribe en una línea un resumen del tema del capítulo o pasaje.","id":"f_fe94cb161b898f"},{"type":"heading","text":"4. Hazlo parte de tu estudio bíblico"},{"type":"field","text":"Lo más importante que aprendí de este video fue:","id":"f_c809060fadbc1a"},{"type":"field","text":"Un error o mal hábito que este método puede ayudarme a evitar es:","id":"f_ae7885edba9c96"},{"type":"field","text":"Un pasaje que quiero estudiar con este método esta semana es:","id":"f_f24ffa0a202fee"},{"type":"heading","text":"Mi plan de memorización"},{"type":"check","id":"f_b77656e6397cfc","text":"Repetiré el pasaje en voz alta."},{"type":"check","id":"f_26378edc8c9481","text":"Trabajaré en secciones pequeñas."},{"type":"check","id":"f_980458d1acce5b","text":"Enfatizaré palabras individuales para notar su significado."},{"type":"check","id":"f_2f7844417a31dd","text":"Repasaré el pasaje todos los días."},{"type":"check","id":"f_c35e0f0000bf49","text":"Conectaré el pasaje con el contexto de su capítulo o tema."},{"type":"heading","text":"Registro de memorización de 7 días"},{"type":"grid","columns":["Día","Leer en voz alta","Recitar de memoria","Notas"],"rows":[{"label":"1","cells":[{"id":"f_435d9b22ff0a13","type":"check","text":"1 — Leer en voz alta"},{"id":"f_ea3e9ee0912951","type":"check","text":"1 — Recitar de memoria"},{"id":"f_ee3664ab0926b6","type":"field","text":"1 — Notas"}]},{"label":"2","cells":[{"id":"f_cde137c1ce5ce2","type":"check","text":"2 — Leer en voz alta"},{"id":"f_f79d8bc73e803a","type":"check","text":"2 — Recitar de memoria"},{"id":"f_7cb24e85f1a717","type":"field","text":"2 — Notas"}]},{"label":"3","cells":[{"id":"f_076e8dc19fca7a","type":"check","text":"3 — Leer en voz alta"},{"id":"f_7a42c55758ef42","type":"check","text":"3 — Recitar de memoria"},{"id":"f_0c6132c9143b0c","type":"field","text":"3 — Notas"}]},{"label":"4","cells":[{"id":"f_51e9e9e62f7f5f","type":"check","text":"4 — Leer en voz alta"},{"id":"f_6b3a5d7793427e","type":"check","text":"4 — Recitar de memoria"},{"id":"f_b88c9ff77150b2","type":"field","text":"4 — Notas"}]},{"label":"5","cells":[{"id":"f_8e4d7df4c3e479","type":"check","text":"5 — Leer en voz alta"},{"id":"f_e2f9f3637123b4","type":"check","text":"5 — Recitar de memoria"},{"id":"f_0e79ca63ae30dd","type":"field","text":"5 — Notas"}]},{"label":"6","cells":[{"id":"f_e6c08f798f4d03","type":"check","text":"6 — Leer en voz alta"},{"id":"f_d98639eb314e2b","type":"check","text":"6 — Recitar de memoria"},{"id":"f_e94a970c4a4270","type":"field","text":"6 — Notas"}]},{"label":"7","cells":[{"id":"f_11ee44cfbf1b77","type":"check","text":"7 — Leer en voz alta"},{"id":"f_10685c3997f371","type":"check","text":"7 — Recitar de memoria"},{"id":"f_d4729ac4270219","type":"field","text":"7 — Notas"}]}]},{"type":"field","text":"Mi próxima acción dentro de las próximas 24 horas:","id":"f_873c025252324c"},{"type":"heading","text":"5. Observaciones de ejemplo de la lección en video"},{"type":"text","text":"Estas son observaciones de ejemplo tomadas de la lección en video. No pretenden reemplazar tu propio estudio cuidadoso del pasaje."},{"type":"text","text":"• La lección comienza con la historia de prisioneros que usaron las Escrituras que recordaban y otros materiales memorizados como fuente de fortaleza durante el cautiverio."},{"type":"text","text":"• Cita pasajes como Colosenses 3:2, Deuteronomio 6:6-9, Isaías 26:3 y Salmo 119:11 para enfatizar la importancia de mantener la Palabra de Dios en la mente y el corazón."},{"type":"text","text":"• La tentación de Jesús en Lucas 4 se usa para mostrar a Jesús respondiendo a la tentación con pasajes de Deuteronomio."},{"type":"text","text":"• Proverbios 3:5-6 se usa como ejemplo de repetición, mientras que Juan 1:1 se usa para demostrar cómo enfatizar cada palabra."},{"type":"text","text":"• La lección también recomienda aprender los temas principales de los capítulos bíblicos, usando Génesis como ejemplo de cómo construir un mapa mental."},{"type":"heading","text":"Tu resumen final"},{"type":"field","text":"Explica este método de Bible Decoded a un amigo en 3 a 5 oraciones.","id":"f_fcb23807c137da"},{"type":"field","text":"Escribe una pregunta que todavía tengas después de completar este cuaderno.","id":"f_77f671d033d986"},{"type":"text","text":"No te apresures al siguiente método. Usa primero este método con un pasaje real. La habilidad crece con la práctica."}]')
ON CONFLICT(id) DO UPDATE SET
  blocks=excluded.blocks,
  updated_at=strftime('%Y-%m-%dT%H:%M:%fZ','now');

INSERT INTO bd_content(id, blocks)
VALUES ('es:word-search', '[{"type":"field","id":"f_79c2f36796bcc5","text":"Nombre","short":true},{"type":"field","id":"f_c07d0ef157c061","text":"Fecha de inicio","short":true},{"type":"heading","text":"Actitud para estudiar con Bible Decoded"},{"type":"text","text":"El Video 1 estableció cuatro preguntas que conviene tener presentes al usar cada método de Bible Decoded."},{"type":"heading","text":"Mantén contigo estas cuatro preguntas"},{"type":"check","id":"f_7e4ef55f7cbffa","text":"Ora por la guía del Espíritu Santo."},{"type":"check","id":"f_085e5d28c63137","text":"Pregunta: ¿Qué me dice esto acerca del carácter de Dios?"},{"type":"check","id":"f_cd15f13f23aef7","text":"Pregunta: ¿De qué manera esto es redentor?"},{"type":"check","id":"f_49fa4e22912f4b","text":"Pregunta: ¿Qué significa esto en mi vida?"},{"type":"text","text":"La lección introductoria también advierte que las herramientas de estudio pueden usarse mal. Explora con libertad, pero sigue comprobando tus conclusiones con el pasaje y su contexto."},{"type":"field","text":"¿Qué es lo que más quieres que este método te ayude a ver o comprender?","id":"f_2c93f115cda37f"},{"type":"heading","text":"1. Aprende la lección"},{"type":"text","text":"Al terminar este cuaderno, deberías poder:"},{"type":"check","id":"f_9f026d6ee0bdf9","text":"Identifica una palabra o frase clave que valga la pena investigar."},{"type":"check","id":"f_0272a539112a52","text":"Compara cómo usa la Biblia esa palabra en varios pasajes."},{"type":"check","id":"f_8bcfe09c0bba84","text":"Usa una concordancia para encontrar apariciones de una palabra."},{"type":"check","id":"f_2886449aa63186","text":"Usa léxicos hebreos o griegos y números de Strong cuando sea útil profundizar."},{"type":"check","id":"f_1a80d60d96e4d2","text":"Anota una conclusión respaldada por los pasajes que examinaste."},{"type":"heading","text":"La lección de un vistazo"},{"type":"text","text":"Comienza con la Biblia"},{"type":"text","text":"La lección enfatiza dejar que la Escritura ayude a definir cómo usa la propia Escritura una palabra."},{"type":"text","text":"Encuentra apariciones"},{"type":"text","text":"Usa una concordancia para localizar la misma palabra o frase en otros pasajes."},{"type":"text","text":"Profundiza cuando sea necesario"},{"type":"text","text":"Usa léxicos hebreos y griegos, la Concordancia Exhaustiva de Strong y Blue Letter Bible."},{"type":"text","text":"Compara contextos"},{"type":"text","text":"No trates una definición de diccionario como si fuera todo el estudio; compara cómo se usa la palabra en su contexto."},{"type":"text","text":"Expresa el resultado"},{"type":"text","text":"Escribe qué parece significar la palabra en los pasajes que estudiaste y por qué."},{"type":"field","text":"En tus propias palabras, ¿cuál es la habilidad o idea principal que enseña esta lección?","id":"f_5b8c29e3bf1179"},{"type":"field","text":"¿Qué parte te resulta más clara? ¿Cuál necesita más reflexión?","id":"f_85b21036c5cab4"},{"type":"heading","text":"2. Práctica guiada"},{"type":"callout","text":"Juan 17:12 + 2 Tesalonicenses 2:3","body":"La lección usa la frase «hijo de perdición» como un estudio sencillo de palabra/frase porque aparece en estos dos pasajes."},{"type":"field","text":"Escribe la frase que estás estudiando y las dos referencias donde la lección la encuentra.","id":"f_407f913b029bd0"},{"type":"field","text":"¿A qué persona se refiere la frase en Juan 17:12?","id":"f_b231477fdbc8fe"},{"type":"field","text":"¿A qué persona o figura se refiere la frase en 2 Tesalonicenses 2:3?","id":"f_e556e020421881"},{"type":"field","text":"¿Qué semejanzas o contrastes notas entre los dos contextos?","id":"f_e6de5031825fb2"},{"type":"field","text":"¿Qué pregunta investigarías después usando una concordancia o un léxico?","id":"f_b59bb2e6d6ee1e"},{"type":"heading","text":"Proceso de estudio de palabras"},{"type":"check","id":"f_e09d1b5bfcbead","text":"Identifica la palabra o frase."},{"type":"check","id":"f_f511db294ec85d","text":"Encuentra otras apariciones con una concordancia."},{"type":"check","id":"f_e5a4568bed11ed","text":"Lee cada aparición en su contexto."},{"type":"check","id":"f_0d1eeb3a479560","text":"Usa el número de Strong o un léxico hebreo/griego si es necesario."},{"type":"check","id":"f_cb5e8cc994db4b","text":"Escribe una conclusión respaldada por los pasajes, no por una sola línea de un diccionario."},{"type":"heading","text":"3. Tu turno"},{"type":"callout","text":"Éxodo 33:18 + Éxodo 34:5-7","body":"La lección presenta «gloria» como ejemplo de estudio de palabras y conecta la petición de Moisés de ver la gloria de Dios con la descripción que sigue."},{"type":"field","text":"Escribe la palabra clave que estás estudiando.","id":"f_1b186caa0d86ea"},{"type":"field","text":"¿Qué sucede en Éxodo 33:18?","id":"f_d29abd3f32612c"},{"type":"field","text":"¿Qué dice Éxodo 34:5-7 cuando el Señor responde?","id":"f_64495c6fe39428"},{"type":"field","text":"Enumera ideas o descripciones repetidas que parezcan relacionadas con la palabra.","id":"f_321e39cfe02c95"},{"type":"field","text":"Basándote solo en estos pasajes, ¿qué conclusión provisional escribirías?","id":"f_0bdf67346dc061"},{"type":"field","text":"¿Qué otros pasajes buscarías antes de fortalecer la conclusión?","id":"f_bfc7c5188b96b6"},{"type":"heading","text":"4. Hazlo parte de tu estudio bíblico"},{"type":"field","text":"Lo más importante que aprendí de este método extra fue:","id":"f_1b26a2c4c48104"},{"type":"field","text":"Un error o mal hábito que este método puede ayudarme a evitar es:","id":"f_aa092864667d82"},{"type":"field","text":"Una palabra o frase que quiero estudiar con este método esta semana es:","id":"f_644d5ab0009637"},{"type":"heading","text":"Mi comprobación de estudio de palabras"},{"type":"check","id":"f_40882000a1921c","text":"Identifiqué una palabra o frase específica."},{"type":"check","id":"f_f470fa6aab5351","text":"Encontré otras apariciones."},{"type":"check","id":"f_fa89317f0a86b0","text":"Leí las apariciones en contexto."},{"type":"check","id":"f_29a353d3935956","text":"Usé un léxico o información de Strong solo cuando fue útil."},{"type":"check","id":"f_0b98a68d1512af","text":"Escribí una conclusión respaldada por los pasajes que estudié."},{"type":"field","text":"Mi próxima acción dentro de las próximas 24 horas:","id":"f_08d24661b0f486"},{"type":"heading","text":"5. Observaciones de ejemplo del método extra"},{"type":"text","text":"Estas son observaciones de ejemplo tomadas de la lección. No pretenden reemplazar tu propio estudio cuidadoso del pasaje."},{"type":"text","text":"• La lección comienza con una historia sobre cómo entender mal una sola palabra puede tener consecuencias graves y luego conecta ese principio con palabras bíblicas como juicio, castigo, ira y para siempre."},{"type":"text","text":"• «Hijo de perdición» se usa como un estudio sencillo de una frase al comparar Juan 17:12 con 2 Tesalonicenses 2:3."},{"type":"text","text":"• La lección explica que un léxico es un diccionario específico de un idioma que también puede proporcionar información etimológica y gramatical."},{"type":"text","text":"• Una concordancia se describe como una lista que muestra dónde aparece una palabra, usando como ejemplo la Concordancia Exhaustiva de Strong."},{"type":"text","text":"• Blue Letter Bible se presenta como un lugar integral para acceder a herramientas de estudio de palabras, y se sugieren «gloria», «fuego», «nube» y «humo» como temas de estudio."},{"type":"heading","text":"Tu resumen final"},{"type":"field","text":"Explica la idea principal de esta lección a un amigo en 3 a 5 oraciones.","id":"f_26d4a1a4a3e4ab"},{"type":"field","text":"Escribe una pregunta que todavía tengas después de completar este cuaderno.","id":"f_3e84f9dde676b5"},{"type":"text","text":"No te apresures. Usa primero lo que aprendiste con un pasaje bíblico real. La habilidad crece con la práctica."}]')
ON CONFLICT(id) DO UPDATE SET
  blocks=excluded.blocks,
  updated_at=strftime('%Y-%m-%dT%H:%M:%fZ','now');

INSERT INTO bd_content(id, blocks)
VALUES ('es:study-lab', '[{"type":"heading","text":"Fundamentos"},{"type":"field","id":"passage","text":"Pasaje bíblico que estoy estudiando","short":true},{"type":"field","id":"translation","text":"Traducción de la Biblia","short":true},{"type":"field","id":"prayer","text":"Comienza con oración. ¿Qué quieres comprender?"},{"type":"heading","text":"Quién / Qué / Cuándo / Dónde / Por qué / Cómo"},{"type":"field","id":"who","text":"¿Quién?"},{"type":"field","id":"what","text":"¿Qué?"},{"type":"field","id":"when","text":"¿Cuándo?"},{"type":"field","id":"where","text":"¿Dónde?"},{"type":"field","id":"why","text":"¿Por qué?"},{"type":"field","id":"how","text":"¿Cómo?"},{"type":"heading","text":"Busca a Cristo"},{"type":"field","id":"christ","text":"¿Dónde ves a Cristo o su obra en este pasaje? ¿Qué detalles respaldan esa conexión?"},{"type":"field","id":"my-place","text":"¿Dónde te ves a ti mismo en la historia?"},{"type":"heading","text":"Reconocimiento de patrones"},{"type":"field","id":"pattern-steps","text":"Divide el pasaje en pasos. ¿Qué secuencia observas?"},{"type":"field","id":"pattern-elsewhere","text":"¿Dónde más ves este patrón? Enumera los pasajes, las semejanzas y las diferencias."},{"type":"field","id":"pattern-god","text":"¿Qué podría enseñarte este patrón acerca de Dios?"},{"type":"heading","text":"Exégesis"},{"type":"field","id":"context","text":"¿Cuál es el contexto histórico y literario? ¿Quién escribió esto y a quién?"},{"type":"field","id":"genre","text":"¿Qué tipo de escrito es este? ¿Qué viene antes y después del pasaje?"},{"type":"field","id":"author-message","text":"¿Qué pretendía comunicar el autor a la audiencia original?"},{"type":"heading","text":"Búsqueda de palabras"},{"type":"field","id":"word","text":"¿Qué palabras o frases necesitan un estudio más detenido?"},{"type":"field","id":"word-references","text":"Anota otras apariciones, sus contextos y cualquier hallazgo útil de una concordancia o léxico."},{"type":"heading","text":"Aplicación"},{"type":"field","id":"character","text":"¿Qué revela esto acerca del carácter de Dios?"},{"type":"field","id":"redemption","text":"¿De qué manera esto es redentor?"},{"type":"field","id":"application","text":"¿Qué significa esto en tu vida? Indica un próximo paso práctico."},{"type":"heading","text":"Memoriza un pasaje"},{"type":"field","id":"memory-passage","text":"¿Qué pasaje vas a memorizar?"},{"type":"field","id":"memory-plan","text":"Escribe el pasaje y tu plan para practicarlo y repasarlo."},{"type":"heading","text":"Comprobación de seguridad interpretativa"},{"type":"check","id":"check-prayer","text":"Oré pidiendo la guía del Espíritu Santo."},{"type":"check","id":"check-context","text":"Leí el pasaje en su contexto inmediato y más amplio."},{"type":"check","id":"check-evidence","text":"Puedo señalar evidencia en el texto que respalda mis conclusiones."},{"type":"check","id":"check-assumptions","text":"Separé lo que dice el texto de mis suposiciones y de mi aplicación personal."},{"type":"check","id":"check-scripture","text":"Comparé mi interpretación con otras Escrituras."},{"type":"check","id":"check-humility","text":"Estoy dispuesto a revisar mi conclusión a medida que aprendo más."},{"type":"field","id":"open-questions","text":"¿Qué preguntas quedan? ¿Qué deberías investigar después?"},{"type":"field","id":"summary","text":"Resume tu estudio en tus propias palabras."}]')
